import sys
import traceback


def _test(expected, actual, call):
    try:
        assert actual == expected, f"{call} should return {expected}. Your code: {actual}"
        print(f"\u2713 passed: {call} \u2192 {expected}")
    except AssertionError as ae:
        print(f"\u2717 failed: {ae}")


class FootMeasureTests:

    def __init__(self, module_name):
        self.module = module_name
        self.FootMeasure = self.module.FootMeasure

    def test_01_zero_measure(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            fm = self.FootMeasure(0, 0)
            _test("0 ft. 0 ins.", str(fm), "str(FootMeasure(0, 0))")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_02_simple_measure(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            fm = self.FootMeasure(5, 0)
            _test("5 ft. 0 ins.", str(fm), "str(FootMeasure(5, 0))")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_03_inches_only(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            fm = self.FootMeasure(0, 7)
            _test("0 ft. 7 ins.", str(fm), "str(FootMeasure(0, 7))")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_04_normalization(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            fm = self.FootMeasure(4, 15)  # should become 5 ft. 3 ins.
            _test("5 ft. 3 ins.", str(fm), "str(FootMeasure(4, 15))")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_05_addition_simple(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            a = self.FootMeasure(2, 6)
            b = self.FootMeasure(1, 3)
            c = a + b  # 3 ft. 9 ins.
            _test("3 ft. 9 ins.", str(c), "str(FootMeasure(2, 6) + FootMeasure(1, 3))")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_06_addition_with_carry(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            a = self.FootMeasure(1, 10)
            b = self.FootMeasure(2, 5)
            c = a + b  # 4 ft. 3 ins.
            _test("4 ft. 3 ins.", str(c), "str(FootMeasure(1, 10) + FootMeasure(2, 5))")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_07_equality_true(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            a = self.FootMeasure(5, 0)
            b = self.FootMeasure(4, 12)  # normalized to 5 ft. 0 ins.
            _test(True, a == b, "FootMeasure(5,0) == FootMeasure(4,12)")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_08_equality_false(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            a = self.FootMeasure(5, 1)
            b = self.FootMeasure(5, 0)
            _test(False, a == b, "FootMeasure(5,1) == FootMeasure(5,0)")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_09_greater_than(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            a = self.FootMeasure(6, 0)
            b = self.FootMeasure(5, 11)
            _test(True, a > b, "FootMeasure(6,0) > FootMeasure(5,11)")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_10_less_than(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            a = self.FootMeasure(3, 6)
            b = self.FootMeasure(4, 0)
            _test(True, a < b, "FootMeasure(3,6) < FootMeasure(4,0)")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_11_greater_equal_and_less_equal(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            a = self.FootMeasure(5, 6)
            b = self.FootMeasure(5, 6)
            c = self.FootMeasure(5, 5)
            _test(True, a >= b, "FootMeasure(5,6) >= FootMeasure(5,6)")
            _test(True, c <= a, "FootMeasure(5,5) <= FootMeasure(5,6)")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_all(self):
        self.test_01_zero_measure()
        self.test_02_simple_measure()
        self.test_03_inches_only()
        self.test_04_normalization()
        self.test_05_addition_simple()
        self.test_06_addition_with_carry()
        self.test_07_equality_true()
        self.test_08_equality_false()
        self.test_09_greater_than()
        self.test_10_less_than()
        self.test_11_greater_equal_and_less_equal()
